import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadEastKolkataData(){const e=readFileSync(resolve(__dirname,"../../frontend/east-kolkata-wetlands-explorer/east-kolkata-data.js"),"utf-8");return new Function(e+"\nreturn { EAST_KOLKATA_INFO, ECOLOGY_HYDROLOGY, WILDLIFE_SPECIES, MAP_HOTSPOTS, GALLERY_IMAGES };")()}function loadWetlandsLandingData(){let e=readFileSync(resolve(__dirname,"../../frontend/wetlands/wetlands-data.js"),"utf-8");e=e.replace(/export\s+const\s+/g,"const ");return new Function(e+"\nreturn WETLANDS_DATA;")()}describe("East Kolkata Wetlands Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadEastKolkataData()}),describe("EAST_KOLKATA_INFO metadata",()=>{it("contains correct wetland metadata and status",()=>{expect(e.EAST_KOLKATA_INFO.id).toBe("east-kolkata-wetlands-explorer"),expect(e.EAST_KOLKATA_INFO.name).toContain("East Kolkata"),expect(e.EAST_KOLKATA_INFO.ramsarYear).toBe(2002),expect(e.EAST_KOLKATA_INFO.ramsarSiteNo).toBe(1208),expect(e.EAST_KOLKATA_INFO.state).toBe("West Bengal")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.EAST_KOLKATA_INFO.quickStats)).toBe(!0),expect(e.EAST_KOLKATA_INFO.quickStats.length).toBe(6)})}),describe("ECOLOGY_HYDROLOGY",()=>{it("contains unescoRecognition, ramsarSite, wastewaterManagement, fisheries, biodiversity, and localLivelihood",()=>{expect(e.ECOLOGY_HYDROLOGY.unescoRecognition).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.ramsarSite).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.wastewaterManagement).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.fisheries).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.biodiversity).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.localLivelihood).toBeDefined()})}),describe("WILDLIFE_SPECIES catalog",()=>{it("is a non-empty array of wetland species",()=>{expect(Array.isArray(e.WILDLIFE_SPECIES)).toBe(!0),expect(e.WILDLIFE_SPECIES.length).toBeGreaterThanOrEqual(4)}),it("includes Fishing Cat",()=>{const t=e.WILDLIFE_SPECIES.find(e=>"fishing-cat"===e.id);expect(t).toBeDefined()})}),describe("Landing Page Integration",()=>{it("is integrated in WETLANDS_DATA landing page dataset",()=>{const e=loadWetlandsLandingData().wetlands.find(e=>"east-kolkata-wetlands"===e.id);expect(e).toBeDefined(),expect(e.exploreUrl).toBe("../east-kolkata-wetlands-explorer/index.html")})})});